def origin_flags(self, source, path, text):
    flags = []
    attribution_lines = []
    for number, line in enumerate(text.splitlines(), 1):
        if self.structure.import_pattern.search(line):
            attribution_lines.append(number)
    if attribution_lines:
        flags.append("apparent_import_attribution_requires_origin_review")
    if source["requested_repo"] == "openai/plugins":
        parts = PurePosixPath(path).parts
        plugin = parts[1] if len(parts) > 1 else ""
        known_imports = {
            "cloudflare": "cloudflare/skills", "superpowers": "obra/superpowers",
            "supabase": "supabase/agent-skills", "sentry": "getsentry/skills",
            "vercel": "vercel-labs/agent-skills"
        }
        if plugin in known_imports:
            flags.append("known_provider_packaging_not_new_origin:" + known_imports[plugin])
    return flags, attribution_lines

def origin_metadata_flags(self, context, data, entry):
    path = PurePosixPath(context["path"])
    parent = path.parent
    if parent.name in {".codex-plugin", ".claude-plugin"}:
        parent = parent.parent
    prefix = "" if str(parent) == "." else str(parent) + "/"
    related = entry["path"].startswith(prefix)
    for basis in entry.get("scope_basis") or []:
        if isinstance(basis, dict) and basis.get("plugin_manifest_path") == context["path"]:
            related = True
    if not related:
        return []
    repository = data.get("repository")
    if isinstance(repository, dict):
        repository = repository.get("url")
    flags = []
    if isinstance(repository, str):
        value = repository.removeprefix("git+").removesuffix(".git")
        parsed = urllib.parse.urlsplit(value)
        if parsed.hostname and parsed.hostname.casefold() == "github.com":
            parts = parsed.path.strip("/").split("/")
            if len(parts) >= 2:
                declared_repo = "/".join(parts[:2])
                if declared_repo.casefold() != entry["repo"].casefold():
                    flags.append("explicit_external_plugin_repository_not_independent_host_origin")
    license_value = data.get("license")
    if isinstance(license_value, str) and re.search(
        r"\bproprietary\b|\bunlicensed\b|all rights reserved|noncommercial|non-commercial",
        license_value, re.IGNORECASE
    ):
        flags.append("restrictive_plugin_license_declaration_conflicts_with_public_child_grant")
    return flags
